 raw=Path(path).read_bytes();assert hashlib.sha256(raw).hexdigest()==EXPECTED;d=json.loads(raw);protocol=d['protocol'];p=d['primary'];assert d['schema']=='causal-shared-unit-lesions-result-v1' and d['status']=='completed';assert protocol['script_sha256']=='105f0c26e0b9fd5e0fa9a6060af48fe4fa900da09ff5e906116da1d12d7caa54' and protocol['runner86_sha256']=='7dc5686028a2fe82d683f091a1f0a08deab25bcc2be41320b5d52e91de6d9714';assert protocol['selected_model_sha256']=='cb7610514c423372362f6cd3512b19f39c156213728c5ecaafe17fe10734e4b0' and not protocol['training_allowed'];assert protocol['evaluation_replicates']==10 and protocol['lesion_budget_semantic_units']==2 and not protocol['ranking_uses_blocking'];assert [x['id'] for x in protocol['motions']]==list(range(498,537))
