 motion=p['motion_results'];assert len(motion)==30 and [x['id'] for x in motion]==list(range(507,537));recognition=p['recognition'];baseline=sum(x['baseline_prediction']==x['action'] for x in motion);private=sum(x['private_prediction']==x['action'] for x in motion);obs=sum(x['observation_lesion_prediction']==x['action'] for x in motion);loss=[x['recognition_margin_loss'] for x in motion];assert (baseline,private,obs)==(recognition['baseline_correct'],recognition['private_correct'],recognition['observation_lesion_correct'])==(30,30,18);assert close(sum(loss)/30,recognition['margin_loss_mean']) and sum(x>0 for x in loss)==recognition['margin_loss_wins']==30;assert recognition['passed']==(baseline>=20 and baseline>=private-2 and sum(loss)/30>0 and sum(x>0 for x in loss)>=18)
